    },
    {
      "card_ids": ["C25"],
      "claim": "Paritaprevir, despite a more complex structure, shows an absolute oral bioavailability of 52.6% in healthy volunteers, supporting the high-F category.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Levosulpiride, a sulfonamide-containing analogue with known absorption limitations, still has an absolute oral bioavailability of 23.4%, which is above the 20% threshold and therefore supports a high prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because the closest analogue glimepiride is essentially completely bioavailable, other sulfonylurea analogues show F values well above 20%, and no experimental evidence indicates F below 20%.",
